import type { ReactElement } from "react";

// The living mark, drawn as SVG (DESIGN.md §8 "The living mark, drawn as SVG") — the kit's `./living-mark` entry: the
// field's own mark (the band that runs the ∞ with its one half-twist, and its three lights), animated, for a load the
// field doesn't draw. Its two files are GENERATED by tooling/splash/living-mark.mjs from the vendored splash — one
// drawing on the app icon's two grounds (§12): `dark` in white ink for the field and smoke, `light` in black ink for
// milk and paper. Each plays the field's own clock in its own document, so the mark is an <img>: no script, no state,
// nothing to start or stop, and at rest by itself under reduced motion.

/** The mark's box, CSS px at the field's own scale (its ∞ 93 wide, as the splash draws it). */
export const LIVING_MARK_SIZE = { width: 99, height: 44 } as const;

/** What the mark stands on. */
export type LivingMarkGround = "dark" | "light";

/** The generated files, by ground. */
export const LIVING_MARK_URL: Readonly<Record<LivingMarkGround, string>> = {
  dark: new URL("./living-mark-dark.svg", import.meta.url).href,
  light: new URL("./living-mark-light.svg", import.meta.url).href,
};

export interface LivingMarkProps {
  /** What it stands on: "dark" (the default) draws it in white ink, "light" in black. */
  readonly ground?: LivingMarkGround;
  /** CSS px wide, its height following; the field draws its own at 99. */
  readonly width?: number;
  /** What a screen reader hears. Without one the mark is decoration: the words beside it say what loads. */
  readonly label?: string;
  readonly className?: string;
}

export function LivingMark({
  ground = "dark",
  width = LIVING_MARK_SIZE.width,
  label,
  className,
}: LivingMarkProps): ReactElement {
  return (
    <img
      src={LIVING_MARK_URL[ground]}
      width={width}
      height={(width * LIVING_MARK_SIZE.height) / LIVING_MARK_SIZE.width}
      alt={label ?? ""}
      aria-hidden={label === undefined ? true : undefined}
      draggable={false}
      className={className}
    />
  );
}
